<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import { useRoute, useRouter, RouterLink } from 'vue-router'
import { products, formatIDR } from '../data/products'
import { useCartStore } from '../stores/cart'
const route=useRoute(), router=useRouter(), cart=useCartStore()
const search=ref(route.query.q||''), region=ref(route.query.region||'Semua'), process=ref('Semua'), sort=ref('featured'), listView=ref(false)
const regions=['Semua','Sumatra','Bali','Sulawesi','Flores','Jawa','Papua','Blend']
const filtered=computed(()=>{let list=products.filter(p=>p.name.toLowerCase().includes(search.value.toLowerCase())||p.origin.toLowerCase().includes(search.value.toLowerCase())||p.tasting.join(' ').toLowerCase().includes(search.value.toLowerCase()));if(region.value!=='Semua')list=list.filter(p=>p.region===region.value);if(process.value!=='Semua')list=list.filter(p=>p.process===process.value);if(sort.value==='price-low')list.sort((a,b)=>a.price-b.price);if(sort.value==='price-high')list.sort((a,b)=>b.price-a.price);if(sort.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name));return list})
function sync(){router.replace({query:{...route.query,q:search.value||undefined,region:region.value==='Semua'?undefined:region.value}})}
function onShortcut(event){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();document.querySelector('.search-field input')?.focus()}}
onMounted(()=>window.addEventListener('keydown',onShortcut))
onUnmounted(()=>window.removeEventListener('keydown',onShortcut))
</script>
<template>
  <div class="shop-page"><section class="shop-intro" data-aos="fade-up"><div><span class="section-index">KATALOG · {{ products.length }} KOPI PILIHAN</span><h1>Temukan rasa<br/><em>yang terasa dekat.</em></h1><p>Setiap biji punya asal. Setiap asal punya karakter.</p></div><div class="shop-intro-side"><span>INDONESIAN COFFEE<br/>CURATED WITH CARE</span><span class="shop-seal">DH<br/><i>ROASTERY</i></span></div></section>
    <div class="shop-toolbar"><label class="search-field"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg><input v-model="search" placeholder="Cari origin, rasa, atau kopi..." @input="sync"/><kbd>⌘ K</kbd></label><label class="sort-control"><span>URUTKAN</span><select v-model="sort" aria-label="Urutkan produk"><option value="featured">Pilihan kami</option><option value="price-low">Harga terendah</option><option value="price-high">Harga tertinggi</option><option value="name">Nama A–Z</option></select></label></div>
    <div class="shop-layout"><aside class="shop-filters"><div class="filter-title"><span>ASAL KOPI</span><span>+</span></div><button v-for="item in regions" :key="item" :class="['filter-option',{selected:region===item}]" @click="region=item;sync()"><span>{{ item }}</span><span>{{ item==='Semua'?products.length:products.filter(p=>p.region===item).length }}</span></button><div class="filter-title process-title"><span>PROSES</span><span>+</span></div><button v-for="item in ['Semua','Washed','Natural','Honey','Wet-hulled','House blend']" :key="item" :class="['filter-option',{selected:process===item}]" @click="process=item"><span>{{ item==='Semua'?'Semua proses':item }}</span><span v-if="process===item">✓</span></button><div class="filter-note"><span>✳</span><p>Semua kopi disangrai dalam batch kecil untuk menjaga kesegarannya.</p></div></aside>
      <div class="shop-results"><div class="results-top"><span>MENAMPILKAN <b>{{ filtered.length }}</b> KOPI</span><div><button :class="{'view-active':!listView}" aria-label="Tampilan grid" :aria-pressed="!listView" @click="listView=false">▦</button><span>·</span><button :class="{'view-active':listView}" aria-label="Tampilan daftar" :aria-pressed="listView" @click="listView=true">☰</button></div></div><div :class="['shop-product-grid',{ 'list-view':listView }]" role="list"><article v-for="(product, index) in filtered" :key="product.id" class="product-card" role="listitem" data-aos="fade-up" :data-aos-delay="Math.min(index * 50, 200)"><div class="product-image-wrap"><RouterLink :to="`/product/${product.id}`" class="product-image-link"><img :src="product.image" :alt="`Kopi ${product.name}`" loading="lazy"/><span class="image-origin">{{ product.region }} <i>↗</i></span></RouterLink><button class="favorite-button" :class="{saved:cart.wishlist.includes(product.id)}" :aria-label="cart.wishlist.includes(product.id)?'Hapus favorit':'Simpan favorit'" @click="cart.toggleWishlist(product.id)"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8l1.1 1.1L12 21l7.8-7.5 1.1-1.1a5.5 5.5 0 0 0-.1-7.8Z"/></svg></button><span class="product-tag">{{ product.badge }}</span></div><div class="product-meta"><span>{{ product.process }}</span><span>{{ product.roastLabel }} roast</span></div><RouterLink :to="`/product/${product.id}`" class="product-title">{{ product.name }}</RouterLink><p class="product-origin">{{ product.origin }} <span>·</span> {{ product.altitude }}</p><div class="product-notes"><span v-for="taste in product.tasting.slice(0,2)" :key="taste">{{ taste }}</span></div><div class="product-card-foot"><span><b>{{ formatIDR(product.price) }}</b><small> / 250g</small></span><button :aria-label="`Tambah ${product.name} ke tas`" @click="cart.add(product.id,'250g','Whole bean')">+</button></div></article><div v-if="!filtered.length" class="region-empty"><span>◌</span><p>Belum ada kopi yang cocok. Coba origin atau rasa lain.</p><button @click="search='';region='Semua';process='Semua';sync()">Atur ulang pencarian</button></div></div></div></div>
  </div>
</template>
